<h1>Limericks About People Named Bill</h1>

<ul>
  </ul>

<script>
  // Sample limericks about people named Bill
  const limericks = [
    "There once was a Bill, an economist bold,\nWho predicted the market would fold,\nBut his theories were wrong,\nAnd his predictions were strong,\nLeaving everyone with a tale to be told.",
    "A Bill named Jurgen, a lawyer so keen,\nHad a case that was quite obscene,\nHe argued with grace,\nWith a smile on his face,\nAnd won the case, a legal machine.",
    // Add more limericks here...
  ];

  const ul = document.querySelector('ul');

  limericks.forEach((limerick) => {
    const li = document.createElement('li');
    li.textContent = limerick;
    ul.appendChild(li);
  });
</script>

</body>
</html>
```

